<script>
import { Component, Prop, Vue } from "vue-property-decorator";

/**
 * This makes working with objects that come from slots easier to work with.
 *
 * Such as:
 * <WrapNode tag="div" :value="$slots.default[0]" />
 */
@Component
export default class WrapNode extends Vue {
  @Prop({ type: Number }) value;

  render(h) {
    let nodes = Array.isArray(this.$slots.default)
      ? this.$slots.default
      : [this.$slots.default];
    nodes = nodes.filter((n) => (n && n.tag) !== void 0);

    if (Array.isArray(nodes)) {
      return h("div", [nodes[this.value]]);
    }

    return h("div", [nodes]);
  }
}
</script>
